-- Pack 22 gate: rules library, ruleset versions, rule citations on discipline records (migrations 20261018000100, 20261018000200).
--   * the Buhurt International document directory matches the source inventory (42 documents + 3 archive folders), and re-running it changes nothing
--   * imports never overwrite published text; drafts and versions in review are owner-only; publishing supersedes, never deletes
--   * published text, versions and history are immutable except through the owner's audited functions (corrections keep the old words)
--   * competitions keep the version they were fought under; organizers only, published versions only, test rulesets only for test events
--   * citing a rule on a Pack 13 disciplinary record: event officials only, append-only, published rules only, final fights for head marshal / organizer
--   * the discipline log is for this event's officials only and carries no account ids
-- Uses the INVENTED example rulesets (rules-library/_example-body, NOT real rules) generated by scripts/rules/release.ts.
-- LOCAL THROWAWAY DATABASE ONLY; everything is rolled back.   Run from the repository root:  psql -v ON_ERROR_STOP=1 -d <db> -f supabase/tests/pack22_gate.sql
\set ON_ERROR_STOP on
begin;

create schema t;
create table t.log (n serial, name text);
create function t.as_anon() returns void language plpgsql as $$ begin reset role; perform set_config('request.jwt.claim.sub', '', true); set local role anon; end $$;
create function t.as_user(u uuid) returns void language plpgsql as $$ begin reset role; perform set_config('request.jwt.claim.sub', u::text, true); set local role authenticated; end $$;
create function t.as_admin() returns void language plpgsql as $$ begin reset role; perform set_config('request.jwt.claim.sub', '', true); end $$;
create function t.expect_error(label text, stmt text, state text default null) returns void language plpgsql as $$
declare ok boolean := false; got text;
begin
  begin execute stmt; exception when others then ok := true; got := sqlstate; end;
  if not ok then raise exception 'FAIL (expected an error): %', label; end if;
  if state is not null and got <> state then raise exception 'FAIL (wrong error % instead of %): %', got, state, label; end if;
  insert into t.log (name) values (label);
end $$;
create function t.expect_eq(label text, got anyelement, want anyelement) returns void language plpgsql as $$
begin
  if got is distinct from want then raise exception 'FAIL (% <> %): %', got, want, label; end if;
  insert into t.log (name) values (label);
end $$;
create function t.u(n int) returns uuid language sql immutable as $$ select ('00000000-0000-0000-0000-' || lpad('c22' || n, 12, '0'))::uuid $$;
create function t.ev(n int) returns uuid language sql immutable as $$ select ('00000000-0000-0000-0000-' || lpad('e22' || n, 12, '0'))::uuid $$;
create function t.k(n int) returns uuid language sql immutable as $$ select ('00000000-0000-0000-0000-' || lpad('c2c' || n, 12, '0'))::uuid $$;
create function t.m(n int) returns uuid language sql immutable as $$ select ('00000000-0000-0000-0000-' || lpad('d22' || n, 12, '0'))::uuid $$;
create function t.d(n int) returns uuid language sql immutable as $$ select ('00000000-0000-0000-0000-' || lpad('dd2' || n, 12, '0'))::uuid $$;
create function t.cmd(n int) returns uuid language sql immutable as $$ select ('00000000-0000-0000-0000-' || lpad('ca2' || n, 12, '0'))::uuid $$;
create function t.ver(doc text, v text) returns uuid language sql stable security definer as $$
  select rv.id from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id where r.inventory_key = doc and rv.version = v $$;
create function t.prov(doc text, v text, num text) returns uuid language sql stable security definer as $$
  select p.id from public.rule_provisions p where p.ruleset_version_id = t.ver(doc, v) and p.number = num and p.kind <> 'appendix' $$;
grant usage on schema t to anon, authenticated, service_role;
grant all on t.log to anon, authenticated, service_role;
grant usage on all sequences in schema t to anon, authenticated, service_role;
grant execute on all functions in schema t to anon, authenticated, service_role;

-- ---------------------------------------------------------------- 1. the Buhurt International document directory (migration 20261018000200)
select t.expect_eq('BI directory: 45 entries from the inventory', (select count(*) from public.rulesets where governing_body = 'Buhurt International')::int, 45);
select t.expect_eq('BI directory: 42 documents and 3 archive folders', (select count(*) filter (where source_host <> 'drive_folder') || '+' || count(*) filter (where source_host = 'drive_folder') from public.rulesets where governing_body = 'Buhurt International'), '42+3');
select t.expect_eq('BI directory: per committee 8 / 6 / 5 / 23 documents',
  (select string_agg(committee || '=' || n, ',' order by committee) from (select committee, count(*) n from public.rulesets where governing_body = 'Buhurt International' and source_host <> 'drive_folder' group by 1) x),
  'authenticity=23,executive=8,marshal=6,tournament=5');
select t.expect_eq('BI directory: every link is the official site file or its Google Drive file',
  (select count(*) from public.rulesets where governing_body = 'Buhurt International' and not (official_url ~ '^https://www\.buhurtinternational\.com/_files/ugd/[A-Za-z0-9_]+\.pdf$' or official_url ~ '^https://drive\.google\.com/(file/d|drive/folders)/'))::int, 0);
select t.expect_eq('BI directory: every entry is classified and traced to the page snapshot',
  (select count(*) from public.rulesets r join public.sources s on s.id = r.inventory_source_id where r.governing_body = 'Buhurt International' and r.kind is not null and s.kind = 'official'
     and s.citation = 'snapshot sha256 68e97d7b29556dfaf0bf34c8c54d5e5f2aafa97bd9d5ae208867b50cfc4b7576' and s.url = 'https://www.buhurtinternational.com/rules')::int, 45);
select t.expect_eq('BI directory: the core rulebooks are there with the format they apply to',
  (select string_agg(inventory_key || ':' || array_to_string(applies_to, '+'), ',' order by inventory_key) from public.rulesets where inventory_key in ('marshal/buhurt-rules', 'marshal/duels-rules', 'marshal/outrance-rules')),
  'marshal/buhurt-rules:buhurt,marshal/duels-rules:duels,marshal/outrance-rules:outrance');
-- The official text (migration 20261018000400, generated from rules-library/buhurt-international/releases/2026-10-06): 42 documents, reconciled.
-- (The earlier editions loaded by 20261018000900 are checked in pack22_history_gate.sql; these checks are about the current release.)
select t.expect_eq('BI release: one version for each of the 42 documents, none for the archive folders',
  (select count(*) || '/' || count(distinct r.id) || '/' || count(*) filter (where r.source_host = 'drive_folder') from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id where r.governing_body = 'Buhurt International' and not rv.historical), '42/42/0');
select t.expect_eq('BI release: every version reconciled, in review (waiting for the owner to publish), from release 2026-10-06, not synthetic',
  (select count(*) from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id where r.governing_body = 'Buhurt International' and not rv.historical
     and rv.status = 'in_review' and (rv.reconciliation ->> 'ok')::boolean and rv.import_release = '2026-10-06' and not rv.synthetic and rv.source_sha256 ~ '^[0-9a-f]{64}$' and rv.page_count > 0)::int, 42);
select t.expect_eq('BI release: 42 different source files', (select count(distinct rv.source_sha256) from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id where r.governing_body = 'Buhurt International' and not rv.historical)::int, 42);
select t.expect_eq('BI release: no provision is left needing review, and every version has text',
  (select count(*) filter (where p.review_status = 'needs_review') || '/' || count(distinct p.ruleset_version_id) from public.rule_provisions p join public.ruleset_versions rv on rv.id = p.ruleset_version_id join public.rulesets r on r.id = rv.ruleset_id where r.governing_body = 'Buhurt International' and not rv.historical), '0/42');
select t.expect_eq('BI release: version labels read from the documents themselves',
  (select string_agg(r.inventory_key || '=' || rv.version, ',' order by r.inventory_key) from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id
    where not rv.historical and r.inventory_key in ('marshal/buhurt-rules', 'marshal/duels-rules', 'tournament/buhurt-regulations', 'authenticity/infractions', 'executive/judiciary-committee', 'marshal/weapon-shield-chart')),
  'authenticity/infractions=26.4,executive/judiciary-committee=2024.06,marshal/buhurt-rules=26.4.1,marshal/duels-rules=26.4,marshal/weapon-shield-chart=26.2.1,tournament/buhurt-regulations=26.4');
select t.expect_eq('BI release: a picture-only page is a figure with no words of BuhurtOS''s own (empty body)',
  (select count(*) filter (where p.body <> '' or not p.has_figures) || '/' || sign(count(*)) from public.rule_provisions p join public.ruleset_versions rv on rv.id = p.ruleset_version_id join public.rulesets r on r.id = rv.ruleset_id
    where r.governing_body = 'Buhurt International' and not rv.historical and p.kind = 'figure'), '0/1');
select t.expect_eq('BI release: text read from page images is marked as OCR',
  (select count(*) from public.rule_provisions p where p.ruleset_version_id = t.ver('authenticity/gauntlets', '26.1') and p.extraction = 'ocr') > 20, true);
select t.expect_eq('BI release: Buhurt Rules 4.12 is "Striking Grounded competitors", word for word (capital G as printed)',
  (select title || ' | ' || body from public.rule_provisions where id = t.prov('marshal/buhurt-rules', '26.4.1', '4.12')), 'Striking Grounded competitors | Striking a grounded competitor is prohibited.');
select t.expect_eq('BI release: tables are stored as rows and cells, not flattened (Duel Regulations 3.2)',
  (select body ~ '\| Category \| End of round \| Break between rounds \| Fight victory \| Technical win \|' and body ~ '\| Sword and buckler \|' from public.rule_provisions where id = t.prov('tournament/duel-regulations', '26.4', '3.2')), true);
select t.as_anon();
select t.expect_eq('BI directory: anonymous visitors can read it', (select count(*) from public.rulesets where governing_body = 'Buhurt International')::int, 45);
select t.expect_eq('BI release: versions still in review are not public', (select count(*) from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id where r.governing_body = 'Buhurt International')::int, 0);
select t.expect_eq('BI release: their provisions are not public either', (select count(*) from public.rule_provisions where ruleset_version_id = (select t.ver('marshal/buhurt-rules', '26.4.1')))::int, 0);
select t.as_admin();
select t.as_admin();
\i supabase/migrations/20261018000200_pack22_bi_document_inventory.sql
select t.expect_eq('BI directory: importing the same inventory again changes nothing',
  (select details ->> 'unchanged' || '/' || (details ->> 'new') || '/' || (details ->> 'changed') from public.audit_log where action = 'rules.inventory_imported' and subject = 'Buhurt International' order by id desc limit 1), '45/0/0');
select t.expect_eq('BI directory: still exactly 45 entries', (select count(*) from public.rulesets where governing_body = 'Buhurt International')::int, 45);
\i supabase/migrations/20261018000400_rules_bi_2026_10_06.sql
select t.expect_eq('BI release: loading the same release again changes nothing',
  (select count(*) from public.audit_log where action = 'rules.version_imported' and (details ->> 'release') = '2026-10-06')::int, 42);
select t.expect_eq('BI conflicts: the tier points disagreement is recorded open, undecided, quoting both sides (League Structure 2.3.4/2.3.5 vs 3.3.2 and Tournament Structure 4.2)',
  (select string_agg(pa.stable_key || '~' || pb.stable_key || ':' || c.status, ',' order by pa.stable_key, pb.stable_key)
     from public.rule_conflicts c join public.rule_provisions pa on pa.id = c.provision_a join public.rule_provisions pb on pb.id = c.provision_b where c.governing_body = 'Buhurt International'),
  'league-structure:2.3.4~league-structure:3.3.2:open,league-structure:2.3.4~tournament-structure:4.2:open,league-structure:2.3.5~league-structure:3.3.2:open');
select t.expect_eq('BI conflicts: each recorded conflict is audited', (select count(*) from public.audit_log where action = 'rules.conflict_noted' and details ->> 'by' = 'Pack 22 import, release 2026-10-06')::int, 3);
\i supabase/migrations/20261018000600_pack22_bi_rule_conflicts.sql
select t.expect_eq('BI conflicts: running the conflicts migration again records nothing new', (select count(*) from public.rule_conflicts where governing_body = 'Buhurt International')::int, 3);
select t.as_anon();
select t.expect_eq('BI conflicts: not public while the documents are in review', (select count(*) from public.rule_conflicts where governing_body = 'Buhurt International')::int, 0);
select t.as_admin();
select t.expect_error('a rules document from the inventory is never deleted', $$delete from public.rulesets where inventory_key = 'marshal/buhurt-rules'$$, 'P0001');

