-- ---------------------------------------------------------------- 3. importing the invented example rulesets
\i supabase/tests/fixtures/pack22_example_r1.sql
\i supabase/tests/fixtures/pack22_example_r2.sql
select t.expect_eq('import: three versions, all in review', (select string_agg(r.inventory_key || ' ' || rv.version || ' ' || rv.status, ', ' order by r.inventory_key, rv.version) from public.ruleset_versions rv join public.rulesets r on r.id = rv.ruleset_id where r.governing_body = 'Example Body (test)'),
  'marshal/example-combat-rules V.1.0 in_review, marshal/example-combat-rules V.1.1 in_review, tournament/example-event-regulations V.2.0 in_review');
select t.expect_eq('import: provision counts match the release reconciliation (15 + 13 + 6)',
  (select string_agg(n::text, '+' order by v) from (select rv.version v, count(*) n from public.rule_provisions p join public.ruleset_versions rv on rv.id = p.ruleset_version_id where rv.synthetic group by 1) x), '15+13+6');
select t.expect_eq('import: every version carries its source checksum, page count and reconciliation',
  (select count(*) from public.ruleset_versions where synthetic and source_sha256 ~ '^[0-9a-f]{64}$' and page_count > 0 and (reconciliation ->> 'ok')::boolean and (reconciliation ->> 'char_coverage')::numeric > 0.99)::int, 3);
select t.expect_eq('import: the database checksum of every provision equals the importer''s',
  (select count(*) from public.rule_provisions where content_sha256 <> private.rule_content_sha256(number, title, body))::int, 0);
select t.expect_eq('import: parents resolve (1.2 is under 1)', (select pp.number from public.rule_provisions p join public.rule_provisions pp on pp.id = p.parent_id where p.id = t.prov('marshal/example-combat-rules', 'V.1.0', '1.2')), '1');
select t.expect_eq('import: page and stable key are traceable', (select page_from || ' ' || stable_key from public.rule_provisions where id = t.prov('marshal/example-combat-rules', 'V.1.0', '3.1')), '2 example-combat-rules:3.1');
select t.expect_eq('import: the same stable key links a rule across versions', (select count(*) from public.rule_provisions where stable_key = 'example-combat-rules:2.1')::int, 2);
select t.expect_eq('import: BuhurtOS search words are stored apart from the official text',
  (select array_to_string(keywords, '|') from public.rule_provisions where id = t.prov('marshal/example-combat-rules', 'V.1.0', '2.1')), 'back of knee|knee');
select t.as_anon();
select t.expect_eq('drafts and reviews are invisible to anonymous visitors', (select count(*) from public.rule_provisions p join public.ruleset_versions v on v.id = p.ruleset_version_id where v.synthetic)::int, 0);
