-- ---------------------------------------------------------------- 5. published meaning is frozen
select t.expect_error('published rule text cannot be edited directly', $$update public.rule_provisions set body = 'changed' where id = t.prov('marshal/example-combat-rules','V.1.0','2.1')$$, 'P0001');
