select t.expect_error('a provision cannot be added to a published version', $$insert into public.rule_provisions (ruleset_version_id, ordinal, kind, body, stable_key, content_sha256) values (t.ver('marshal/example-combat-rules','V.1.1'), 99, 'rule', 'x', 'x:99', repeat('0', 64))$$, 'P0001');
select t.expect_error('a published version cannot be deleted', $$delete from public.ruleset_versions where id = t.ver('marshal/example-combat-rules','V.1.1')$$, 'P0001');
select t.expect_error('a published version''s title cannot change', $$update public.ruleset_versions set title = 'Other' where id = t.ver('marshal/example-combat-rules','V.1.1')$$, 'P0001');
select t.expect_error('a published version cannot go back to review', $$update public.ruleset_versions set status = 'in_review' where id = t.ver('marshal/example-combat-rules','V.1.1')$$, 'P0001');
select t.expect_error('a superseded version cannot be re-published', $$update public.ruleset_versions set status = 'published' where id = t.ver('marshal/example-combat-rules','V.1.0')$$, 'P0001');
select t.expect_error('a changed file for a published version is refused (it must become a new version)',
  $$select private.rules_import_version('{"governing_body":"Example Body (test)","inventory_key":"marshal/example-combat-rules","release":"x","version":{"version":"V.1.0","content_sha256":"2222222222222222222222222222222222222222222222222222222222222222","reconciliation":{"ok":true}},"provisions":[]}'::jsonb)$$, 'P0001');
\i supabase/tests/fixtures/pack22_example_r1.sql
select t.expect_eq('re-running the release after publishing changes nothing', (select status from public.ruleset_versions where id = t.ver('marshal/example-combat-rules', 'V.1.0')), 'superseded');

-- ---------------------------------------------------------------- 6. review gating: a version with open review items or a failed reconciliation is never published
select private.rules_import_version(jsonb_build_object('governing_body', 'Example Body (test)', 'inventory_key', 'tournament/example-event-regulations', 'release', 'gate', 'synthetic', true,
  'version', jsonb_build_object('version', 'V.3.0-draft', 'content_sha256', repeat('3', 64), 'reconciliation', jsonb_build_object('ok', false, 'provisions', 1)),
  'provisions', jsonb_build_array(jsonb_build_object('ordinal', 1, 'kind', 'rule', 'number', '1', 'body', 'Draft text.', 'stable_key', 'example-event-regulations:1', 'content_sha256', private.rule_content_sha256('1', null, 'Draft text.')))));
select t.expect_eq('a release that did not reconcile is stored as a draft', (select status from public.ruleset_versions where id = t.ver('tournament/example-event-regulations', 'V.3.0-draft')), 'draft');
select t.as_user(t.u(5));
select t.expect_error('a draft cannot be published', $$select public.publish_ruleset_version(t.ver('tournament/example-event-regulations','V.3.0-draft'))$$, 'P0001');
select t.as_admin();
select private.rules_import_version(jsonb_build_object('governing_body', 'Example Body (test)', 'inventory_key', 'tournament/example-event-regulations', 'release', 'gate', 'synthetic', true,
  'version', jsonb_build_object('version', 'V.3.0', 'content_sha256', repeat('4', 64), 'reconciliation', jsonb_build_object('ok', true, 'provisions', 2)),
  'provisions', jsonb_build_array(
    jsonb_build_object('ordinal', 1, 'kind', 'section', 'number', '1', 'title', 'Registration', 'body', '', 'stable_key', 'example-event-regulations:1', 'content_sha256', private.rule_content_sha256('1', 'Registration', '')),
    jsonb_build_object('ordinal', 2, 'kind', 'rule', 'number', '1.1', 'body', 'Unclear scan.', 'stable_key', 'example-event-regulations:1.1', 'parent_key', 'example-event-regulations:1', 'review_status', 'needs_review', 'review_note', 'table-like layout',
                       'content_sha256', private.rule_content_sha256('1.1', null, 'Unclear scan.')))));
