-- ---------------------------------------------------------------- 12. functions: privileges
select t.expect_eq('no Pack 22 write function is executable by anon',
  (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public'
     and p.proname in ('publish_ruleset_version', 'withdraw_ruleset_version', 'review_rule_provision', 'correct_rule_provision', 'note_rule_conflict', 'resolve_rule_conflict', 'set_competition_ruleset_version', 'lyst_cite_rule', 'event_discipline_log')
     and has_function_privilege('anon', p.oid, 'execute'))::int, 0);
select t.expect_eq('the importer functions are executable by neither anon nor authenticated',
  (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'private' and p.proname like 'rules_import_%'
     and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute')))::int, 0);
select t.expect_eq('every Pack 22 security definer function pins an empty search_path',
  (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where p.prosecdef and n.nspname in ('public', 'private')
     and (p.proname like '%rule%' or p.proname in ('event_discipline_log', 'set_competition_ruleset_version', 'publish_ruleset_version', 'withdraw_ruleset_version'))
     and not (coalesce(p.proconfig, '{}') @> array['search_path=""']))::int, 0);
select t.expect_eq('RLS is on for every new table',
  (select count(*) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relname in ('rule_provisions', 'rule_provision_revisions', 'rule_conflicts', 'match_discipline_rules') and c.relrowsecurity)::int, 4);

